INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('kyo-kunstarzt', 'KUNST ARZT', 'クンスト・アルツト', 'artist_run_space', 'kyoto', 'active', 2, ARRAY['visual_art']::TEXT[], 'KUNST ARZT is an artist-run gallery near Sanjo and Jingu-michi in Kyoto, run by the artist Mitsuhiro Okamoto. It has a near-weekly programme of solo shows by emerging Kyoto artists and themed curated group shows, usually with the artist in the room. Free entry, 12:00-18:00, closed Mondays; show pages carry English titles and short English bios.', 'Higashiyama / Sanjo-Jingumichi', '155-7 Ebisu-cho, Higashiyama-ku, Kyoto 605-0033 (2F above the flower shop, NE corner of Sanjo and Jingu-michi)', 'http://www.kunstarzt.com/', 'https://www.instagram.com/kunstarzt1/', 'http://www.kunstarzt.com/', ARRAY['artist_run','weekly_shows','emerging_artists','curated_group_shows']::TEXT[], 5, 'yes', 'Free; 12:00-18:00, closed Mondays; English titles and short English bios on most show pages', 'html_calendar', false, 'http://www.kunstarzt.com/', '2026-10-20', 'Current show: Yoko Zeltserman Miyaji, 24 Oct-1 Nov 2026 (artist present every day). Next curated show: Takashi Kunitani curation 11-20 Dec 2026. Site is an old-style hand-built HTML page; dates are in the page body, no feed.', false)
INSERT INTO public.sources (source_id,name,name_ja,source_type,market,status,tier,discipline_focus,about,neighborhood,address,website_url,instagram_url,calendar_url,scene_tags,underground_score,newcomer_friendly,foreigner_notes,scrape_method,needs_verification,evidence_url,verified_at,notes,is_demo) VALUES
  ('tyo-4649', '4649', '4649', 'artist_run_space', 'tokyo', 'active', 2, ARRAY['visual_art']::TEXT[], '4649 is an artist-run gallery in Sugamo, Tokyo, sharing a basement with XYZ collective. Its three founders run exhibitions of emerging artists and take part in international fairs and artist-run networks.', 'Sugamo', 'B02, 2-13-4 Sugamo, Toshima-ku, Tokyo 170-0002', 'https://4-6-4-9.jp/', NULL, NULL, ARRAY['artist_run','curatorial_project','international','basement']::TEXT[], 5, 'yes', 'English-first communication; announcements mostly on Instagram', 'manual', true, 'https://easteast.org/2025/?p=1073', '2026-10-20', 'website_url from the NADA profile, not opened in this pass. Shares the basement with XYZcollective. Instagram handle not verified (do not guess).', false)
