INSERT INTO public.events (event_id,market,source_id,venue_name,title,title_ja,event_type,disciplines,date,end_date,time,end_time,recurrence,price_min,price_max,currency,ticket_url,evidence_url,lineup,description,language_barrier,booking_required,verified_at,is_demo) VALUES
  ('tyo-evt-20261021-kondo-hirameki', 'tokyo', 'SRC075', 'Kagurazaka Session House', 'Ryohei Kondo: ''Flashes of movement'' open class', '近藤良平 ダンスクラス「動きのひらめき」', 'class', ARRAY['dance']::TEXT[], '2026-10-21', NULL, '13:00', '14:50', 'weekly Tue 19:30 & Wed 13:00', 2500, 2500, 'JPY', 'https://session-house.net/class-reservation.html', 'https://session-house.net/contemporarydance_class.html', '近藤良平', 'Condors founder Ryohei Kondo''s playful class for any level: find the moment the body moves you rather than build technique. Also Tue 19:30-21:00. 2500 yen.', 'some', 'recommended', '2026-10-20', false)
INSERT INTO public.events (event_id,market,source_id,venue_name,title,title_ja,event_type,disciplines,date,end_date,time,end_time,recurrence,price_min,price_max,currency,ticket_url,evidence_url,lineup,description,language_barrier,booking_required,verified_at,is_demo) VALUES
  ('tyo-evt-20261021-matsumoto-release', 'tokyo', 'SRC075', 'Kagurazaka Session House', 'Taiju Matsumoto: Release Technique (open class)', '松本大樹 ダンスクラス「リリース・テクニック」', 'class', ARRAY['dance']::TEXT[], '2026-10-21', NULL, '15:00', '16:30', 'weekly Wed 15:00 (beginner level Mon 17:55)', 2500, 2500, 'JPY', 'https://session-house.net/class-reservation.html', 'https://session-house.net/contemporarydance_class.html', '松本大樹', 'Laban/Limon-trained Taiju Matsumoto''s release class: swing with gravity, travel on tilted weight, use only the force needed. Beginner version Mon 17:55-19:25. 2500 yen.', 'some', 'recommended', '2026-10-20', false)
INSERT INTO public.events (event_id,market,source_id,venue_name,title,title_ja,event_type,disciplines,date,end_date,time,end_time,recurrence,price_min,price_max,currency,ticket_url,evidence_url,lineup,description,language_barrier,booking_required,verified_at,is_demo) VALUES
  ('tyo-evt-20261027-kogure-research', 'tokyo', 'SRC075', 'Kagurazaka Session House', 'Kaho Kogure: Movement Research (open class)', '小暮香帆 ダンスクラス「ムーブメントリサーチ」', 'class', ARRAY['dance']::TEXT[], '2026-10-27', NULL, '11:00', '12:30', 'weekly Tue 11:00', 2500, 2500, 'JPY', 'https://session-house.net/class-reservation.html', 'https://session-house.net/contemporarydance_class.html', '小暮香帆', 'Morning research class with dancer-choreographer Kaho Kogure: listen to the body, then move through structure, image and rules. Any level; good for makers seeking creation hints. 2500 yen.', 'some', 'recommended', '2026-10-20', false)
INSERT INTO public.events (event_id,market,source_id,venue_name,title,title_ja,event_type,disciplines,date,end_date,time,end_time,recurrence,price_min,price_max,currency,ticket_url,evidence_url,lineup,description,language_barrier,booking_required,verified_at,is_demo) VALUES
  ('tyo-evt-20261021-ida-cell', 'tokyo', 'SRC075', 'Kagurazaka Session House', 'Asami Ida: ''Waking the body from the cell'' (Ilan Lev-based open class)', '井田亜彩実 細胞から目覚める身体', 'class', ARRAY['dance']::TEXT[], '2026-10-21', NULL, '11:00', '12:30', 'weekly Wed 11:00', 2500, 2500, 'JPY', 'https://session-house.net/class-reservation.html', 'https://session-house.net/contemporarydance_class.html', '井田亜彩実', 'Israeli Ilan Lev method as the base: release effort, circulate energy from inside, then research, improvisation, pairing. Ida danced in Israel 2014-19; any level. 2500 yen.', 'some', 'recommended', '2026-10-20', false)
INSERT INTO public.events (event_id,market,source_id,venue_name,title,title_ja,event_type,disciplines,date,end_date,time,end_time,recurrence,price_min,price_max,currency,ticket_url,evidence_url,lineup,description,language_barrier,booking_required,verified_at,is_demo) VALUES
  ('tyo-evt-20261105-ikegami-contact', 'tokyo', 'SRC075', 'Kagurazaka Session House', 'Takkun Ikegami: Contemporary Contact Technique (open class)', '池上たっくん コンテンポラリー コンタクトテクニッククラス', 'class', ARRAY['dance']::TEXT[], '2026-11-05', NULL, '13:00', '14:50', 'weekly Thu 13:00', 2500, 2500, 'JPY', 'https://session-house.net/class-reservation.html', 'https://session-house.net/contemporarydance_class.html', '池上たっくん', 'Basic training then contact as technique: touch, shared weight, dancing with a partner. Oct 22 & 29 are substitute classes (Onishi/Murai 3-day showing); regular class resumes 5 Nov. 2500 yen.', 'some', 'recommended', '2026-10-20', false)
INSERT INTO public.events (event_id,market,source_id,venue_name,title,title_ja,event_type,disciplines,date,end_date,time,end_time,recurrence,price_min,price_max,currency,ticket_url,evidence_url,lineup,description,language_barrier,booking_required,verified_at,is_demo) VALUES
  ('tyo-evt-20261022-thursday-technique', 'tokyo', 'SRC075', 'Kagurazaka Session House', 'Thursday-morning Dance Technique Basics: Release & Flow (Ota), then Technique to Sequence (Hirata) from 3 Dec', '2026年度 木曜午前クラス 平田友子監修『ダンステクニック基礎クラス』', 'class', ARRAY['dance']::TEXT[], '2026-10-22', NULL, '11:00', '12:30', 'weekly Thu 11:00', 2500, 2500, 'JPY', 'https://session-house.net/class-reservation.html', 'https://session-house.net/contemporarydance_class.html', '太田ゆかり (22 Oct-26 Nov), 平田友子 (3 Dec-25 Mar)', 'Curated Thursday course of contemporary fundamentals: Ota''s floor release & flow block 22 Oct-26 Nov (6 sessions), then Hirata''s ballet-mechanics block from 3 Dec. Single sessions OK, 2500 yen.', 'some', 'recommended', '2026-10-20', false)
INSERT INTO public.events (event_id,market,source_id,venue_name,title,title_ja,event_type,disciplines,date,end_date,time,end_time,recurrence,price_min,price_max,currency,ticket_url,evidence_url,lineup,description,language_barrier,booking_required,verified_at,is_demo) VALUES
  ('tyo-evt-20261026-morii-floorwork', 'tokyo', 'SRC075', 'Kagurazaka Session House', 'Jun Morii: Contemporary Dance Open Class - floorwork x flow x dynamics', '森井淳 コンテンポラリーダンス オープンクラス', 'class', ARRAY['dance']::TEXT[], '2026-10-26', NULL, '10:30', '12:00', '2nd & 4th Mon 10:30', 2500, 2500, 'JPY', 'https://session-house.net/class-reservation.html', 'https://session-house.net/contemporarydance_class.html', '森井淳', 'Twice-monthly morning class from floor to standing with contact elements, by Laban-trained Jun Morii (Jalet/Cherkaoui productions). No experience needed. 2500 yen. Holidays off (23 Nov).', 'some', 'recommended', '2026-10-20', false)
