INSERT INTO public.curators (curator_id,name,name_ja,role_label,market,about,disciplines,affiliations,website_url,instagram_url,evidence_url,verified_at,status) VALUES
  ('kyo-cur-okamoto-mitsuhiro', 'Mitsuhiro Okamoto', '岡本光博', 'Curator', 'kyoto', 'Mitsuhiro Okamoto is an artist who runs KUNST ARZT, an artist-run contemporary art gallery above a flower shop at Sanjo and Jingu-michi in Higashiyama, minutes from the Okazaki museum zone. He writes the gallery''s exhibition texts himself and signs them as KUNST ARZT.
INSERT INTO public.curators (curator_id,name,name_ja,role_label,market,about,disciplines,affiliations,website_url,instagram_url,evidence_url,verified_at,status) VALUES
  ('kyo-cur-ago-satoshi', 'Satoshi Ago', 'あごうさとし', 'Artistic director', 'kyoto', 'Satoshi Ago is a playwright and director and the artistic director of THEATRE E9 KYOTO, the crowdfunded independent black box in Higashi-Kujo south of Kyoto Station, which he opened in June 2019 as representative director of Arts Seed Kyoto. He presents the yearly programme.
INSERT INTO public.curators (curator_id,name,name_ja,role_label,market,about,disciplines,affiliations,website_url,instagram_url,evidence_url,verified_at,status) VALUES
  ('tyo-cur-cobra', 'COBRA', NULL, 'Curator', 'tokyo', 'COBRA is a video and performance artist and co-director of XYZcollective, the artist-run gallery he founded in Setagaya in July 2011 and moved to a Sugamo basement in 2016, where it shares the space with 4649 and THE STEAK HOUSE DOSKOI. The gallery''s own text says it is ''not a collective'' but an artist-run gallery built around curation.
INSERT INTO public.curators (curator_id,name,name_ja,role_label,market,about,disciplines,affiliations,website_url,instagram_url,evidence_url,verified_at,status) VALUES
  ('tyo-cur-miyagi-futoshi', 'Futoshi Miyagi', 'ミヤギフトシ', 'Curator', 'tokyo', 'Futoshi Miyagi is an artist and, with COBRA, co-director of XYZcollective, the artist-run gallery in a Sugamo basement that programmes exhibitions of Japanese and foreign artists with curation as its stated focus. The gallery''s own about page (2026) names the two directors.
INSERT INTO public.curators (curator_id,name,name_ja,role_label,market,about,disciplines,affiliations,website_url,instagram_url,evidence_url,verified_at,status) VALUES
  ('tyo-cur-kobayashi-yuhei', 'Yuhei Kobayashi', '小林優平', 'Curator', 'tokyo', 'Yuhei Kobayashi is an artist and one of the three founders and directors of 4649, the curatorial project and artist-run gallery in Sugamo that shares a basement with XYZcollective. Started in 2016 by three art-school classmates and named 4649 in 2018, it shows emerging foreign artists in Tokyo and takes Tokyo artists abroad through off-site projects and fairs.
INSERT INTO public.curators (curator_id,name,name_ja,role_label,market,about,disciplines,affiliations,website_url,instagram_url,evidence_url,verified_at,status) VALUES
  ('tyo-cur-shimizu-shogo', 'Shogo Shimizu', '清水将吾', 'Curator', 'tokyo', 'Shogo Shimizu is an artist and co-director of 4649, the artist-run gallery and curatorial project in Sugamo founded with Yuhei Kobayashi and Yuu Takamizawa. The space, a basement shared with XYZcollective, is open Thursday to Sunday and programmes shows by emerging artists from other cities and countries, while off-site projects present Tokyo artists abroad.
INSERT INTO public.curators (curator_id,name,name_ja,role_label,market,about,disciplines,affiliations,website_url,instagram_url,evidence_url,verified_at,status) VALUES
  ('tyo-cur-takamizawa-yuu', 'Yuu Takamizawa', '高見澤ゆう', 'Curator', 'tokyo', 'Yuu Takamizawa is an artist and co-director of 4649, the Sugamo artist-run gallery and curatorial project he founded with Yuhei Kobayashi and Shogo Shimizu. He has described the space as answering a shortage of places for young Tokyo artists to show, after many of their peers left for the US or Germany.
INSERT INTO public.curators (curator_id,name,name_ja,role_label,market,about,disciplines,affiliations,website_url,instagram_url,evidence_url,verified_at,status) VALUES
  ('kyo-cur-sakamoto-kosei', 'Kosei Sakamoto', '坂本公成', 'Organiser', 'kyoto', 'Kosei Sakamoto is a choreographer and the co-leader, with Yuko Mori, of Monochrome Circus, the Kyoto contact-improvisation company founded in 1990. Beyond making work, he runs the company''s workshops and jams and co-directs the Kyoto International Dance Workshop Festival ''Kyoto no Atsui Natsu'' with Kyoto Art Center, whose 30th edition ran in 2026 (early-summer edition in May, main edition in August).
INSERT INTO public.curators (curator_id,name,name_ja,role_label,market,about,disciplines,affiliations,website_url,instagram_url,evidence_url,verified_at,status) VALUES
  ('kyo-cur-mori-yuko', 'Yuko Mori', '森裕子', 'Organiser', 'kyoto', 'Yuko Mori is a dancer and the co-leader, with Kosei Sakamoto, of Monochrome Circus, the Kyoto dance company that has worked with contact improvisation and collective improvisation since 1990. The company''s 2026 press material names the two as its joint heads.
